/* ── Piece-set dispatcher (used by the card and Manual Entry board) ── */
function COT_lettersSVG(code) {
  var color = code.charAt(0), type = code.charAt(1);
  var isWhite = color === "w";
  var disc = isWhite ? "#f2f2f2" : "#2c2c2c";
  var ink  = isWhite ? "#2c2c2c" : "#f2f2f2";
  var ring = isWhite ? "#8a8a8a" : "#111111";
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 45 45" width="45" height="45">'
    + '<circle cx="22.5" cy="22.5" r="16.5" fill="' + disc + '" stroke="' + ring + '" stroke-width="1.5"/>'
    + '<text x="22.5" y="29.5" text-anchor="middle" font-family="Georgia, \'Times New Roman\', serif"'
    + ' font-size="21" font-weight="bold" fill="' + ink + '">' + type + '</text></svg>';
}
function COT_woodenSVG(code) {
  var inner = (typeof CHESS_PIECES !== "undefined" && CHESS_PIECES[code]) || "";
  var isWhite = code.charAt(0) === "w";
  if (isWhite) {
    inner = inner.replace(/fill="#fff"/g, 'fill="#eaca94"')
                 .replace(/stroke="#fff"/g, 'stroke="#eaca94"')
                 .replace(/fill="#000"/g, 'fill="#6e4a26"')
                 .replace(/stroke="#000"/g, 'stroke="#6e4a26"');
  } else {
    inner = inner.replace(/fill="#fff"/g, 'fill="#caa274"')
                 .replace(/stroke="#fff"/g, 'stroke="#caa274"')
                 .replace(/fill="#000"/g, 'fill="#5c3b22"')
                 .replace(/stroke="#000"/g, 'stroke="#241509"');
  }
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 45 45" width="45" height="45">' + inner + '</svg>';
}
function COT_blankSVG(code) {
  /* The Letters discs without the letters: plain coloured circles. */
  var isWhite = code.charAt(0) === "w";
  var disc = isWhite ? "#f2f2f2" : "#2c2c2c";
  var ring = isWhite ? "#8a8a8a" : "#111111";
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 45 45" width="45" height="45">'
    + '<circle cx="22.5" cy="22.5" r="16.5" fill="' + disc + '" stroke="' + ring + '" stroke-width="1.5"/></svg>';
}
function COT_pieceSVG(code, setName) {
  if (setName === "letters") return COT_lettersSVG(code);
  if (setName === "wooden") return COT_woodenSVG(code);
  if (setName === "blank") return COT_blankSVG(code);
  if (setName === "blindfold")
    /* Blindfolded: pieces render as nothing. Squares stay tappable (hit
       testing is square-based) and the last-move highlight still shows which
       squares moved, so play continues purely from memory. */
    return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 45 45" width="45" height="45"></svg>';
  var inner = (typeof CHESS_PIECES !== "undefined" && CHESS_PIECES[code]) || "";
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 45 45" width="45" height="45">' + inner + '</svg>';
}

var STUDIO_PIECES={"bB": "data:image/webp;base64,", "bK": "data:image/webp;base64,", "bN": "data:image/webp;base64,", "bP": "data:image/webp;base64,", "bQ": "data:image/webp;base64,", "bR": "data:image/webp;base64,", "wB": "data:image/webp;base64,", "wK": "data:image/webp;base64,", "wN": "data:image/webp;base64,", "wP": "data:image/webp;base64,", "wQ": "data:image/webp;base64,", "wR": "data:image/webp;base64,"};

var STUDIO_ORIGINAL_PIECE = COT_pieceSVG;
COT_pieceSVG = function(code,set) {
 if(set !== 'wooden' || !STUDIO_PIECES[code]) return STUDIO_ORIGINAL_PIECE(code,set);
 return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="100" height="100"><image href="'+STUDIO_PIECES[code]+'" x="0" y="0" width="100" height="100" preserveAspectRatio="xMidYMid meet"/></svg>';
};
